/**
 * Pokector application schema (SPEC §19). Better Auth core tables live in
 * ./auth-schema.ts (generated by `auth generate` — do not edit by hand).
 *
 * Conventions:
 * - All money columns are integer minor units (USD cents / EUR cents).
 * - Calendar-day columns (recorded_date, snapshot_date) are `text` "YYYY-MM-DD"
 *   so unique-per-day constraints are timezone-unambiguous (UTC).
 * - Timestamps are integer epoch milliseconds.
 * - Catalog rows use external Pokémon TCG API IDs as primary keys and are never
 *   cascade-deleted by user actions.
 */

import { sql } from "drizzle-orm";
import {
  index,
  integer,
  primaryKey,
  sqliteTable,
  text,
  uniqueIndex,
} from "drizzle-orm/sqlite-core";

import { CARD_VARIANTS, CONDITIONS, GRADES, PRICE_SOURCES } from "../enums";
import { user } from "./auth-schema";

export * from "./auth-schema";
// Re-export the imported enum arrays so existing `schema.CARD_VARIANTS`
// server references keep working (single source of truth in ~/lib/enums).
export { CARD_VARIANTS, CONDITIONS, GRADES, PRICE_SOURCES };

const createdAt = () =>
  integer("created_at", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull();

const updatedAt = () =>
  integer("updated_at", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .$onUpdate(() => new Date())
    .notNull();

// ── Users ────────────────────────────────────────────────────────────────────

export const userProfiles = sqliteTable("user_profiles", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  // Role source of truth is user.role (Better Auth admin plugin); kept here only
  // as a denormalized copy for queries that join profiles.
  role: text("role", { enum: ["user", "admin"] })
    .default("user")
    .notNull(),
  displayName: text("display_name"),
  username: text("username").unique(),
  defaultCurrency: text("default_currency", { enum: ["USD", "EUR"] })
    .default("USD")
    .notNull(),
  locale: text("locale").default("en-US").notNull(),
  timezone: text("timezone").default("UTC").notNull(),
  theme: text("theme", { enum: ["light", "dark", "system"] })
    .default("system")
    .notNull(),
  onboardingCompleted: integer("onboarding_completed", { mode: "boolean" })
    .default(false)
    .notNull(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

// ── Catalog ──────────────────────────────────────────────────────────────────

export const pokemonSets = sqliteTable(
  "pokemon_sets",
  {
    /** External set ID from the Pokémon TCG API (e.g. "sv1"). */
    id: text("id").primaryKey(),
    slug: text("slug").notNull().unique(),
    name: text("name").notNull(),
    nameNormalized: text("name_normalized").notNull(),
    series: text("series").notNull(),
    printedTotal: integer("printed_total"),
    total: integer("total"),
    /** "YYYY-MM-DD" as provided by the source. */
    releaseDate: text("release_date"),
    symbolUrl: text("symbol_url"),
    logoUrl: text("logo_url"),
    sourceUpdatedAt: text("source_updated_at"),
    syncedAt: integer("synced_at", { mode: "timestamp_ms" }).notNull(),
    active: integer("active", { mode: "boolean" }).default(true).notNull(),
  },
  (t) => [
    index("idx_sets_series").on(t.series),
    index("idx_sets_release_date").on(t.releaseDate),
    index("idx_sets_name_normalized").on(t.nameNormalized),
  ],
);

export const pokemonCards = sqliteTable(
  "pokemon_cards",
  {
    /** External card ID from the Pokémon TCG API (e.g. "sv1-25"). */
    id: text("id").primaryKey(),
    slug: text("slug").notNull().unique(),
    setId: text("set_id")
      .notNull()
      .references(() => pokemonSets.id),
    name: text("name").notNull(),
    nameNormalized: text("name_normalized").notNull(),
    number: text("number").notNull(),
    /** Numeric prefix of `number` for correct ordering ("25a" → 25). */
    numberSort: integer("number_sort").notNull(),
    supertype: text("supertype"),
    subtypesJson: text("subtypes_json"),
    hp: integer("hp"),
    typesJson: text("types_json"),
    rarity: text("rarity"),
    artist: text("artist"),
    nationalPokedexNumbersJson: text("national_pokedex_numbers_json"),
    regulationMark: text("regulation_mark"),
    imageSmallUrl: text("image_small_url"),
    imageLargeUrl: text("image_large_url"),
    tcgplayerUrl: text("tcgplayer_url"),
    cardmarketUrl: text("cardmarket_url"),
    /** Lower-cased searchable haystack (name + set + number + rarity + types). */
    searchText: text("search_text").notNull(),
    sourceUpdatedAt: text("source_updated_at"),
    syncedAt: integer("synced_at", { mode: "timestamp_ms" }).notNull(),
    active: integer("active", { mode: "boolean" }).default(true).notNull(),
  },
  (t) => [
    index("idx_cards_set").on(t.setId),
    index("idx_cards_name_normalized").on(t.nameNormalized),
    index("idx_cards_rarity").on(t.rarity),
    index("idx_cards_set_number").on(t.setId, t.numberSort, t.number),
  ],
);

// ── Pricing ──────────────────────────────────────────────────────────────────

export const cardPricesCurrent = sqliteTable(
  "card_prices_current",
  {
    cardId: text("card_id")
      .notNull()
      .references(() => pokemonCards.id),
    source: text("source", { enum: PRICE_SOURCES }).notNull(),
    variant: text("variant", { enum: CARD_VARIANTS }).notNull(),
    currency: text("currency", { enum: ["USD", "EUR"] }).notNull(),
    /** Selected value: TCGplayer market→mid→low; Cardmarket trend→avgSell→low. */
    normalizedPriceMinor: integer("normalized_price_minor").notNull(),
    lowMinor: integer("low_minor"),
    midMinor: integer("mid_minor"),
    highMinor: integer("high_minor"),
    marketMinor: integer("market_minor"),
    directLowMinor: integer("direct_low_minor"),
    trendMinor: integer("trend_minor"),
    averageSellMinor: integer("average_sell_minor"),
    /** Source's own updatedAt ("YYYY/MM/DD" normalized to "YYYY-MM-DD"). */
    sourceUpdatedAt: text("source_updated_at"),
    observedAt: integer("observed_at", { mode: "timestamp_ms" }).notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.cardId, t.source, t.variant, t.currency] }),
    index("idx_prices_source_observed").on(t.source, t.observedAt),
  ],
);

export const trackedCards = sqliteTable(
  "tracked_cards",
  {
    cardId: text("card_id")
      .primaryKey()
      .references(() => pokemonCards.id),
    collectionReferenceCount: integer("collection_reference_count").default(0).notNull(),
    wishlistReferenceCount: integer("wishlist_reference_count").default(0).notNull(),
    popularityScore: integer("popularity_score").default(0).notNull(),
    lastViewedAt: integer("last_viewed_at", { mode: "timestamp_ms" }),
    lastHistoryAt: integer("last_history_at", { mode: "timestamp_ms" }),
    updatedAt: updatedAt(),
  },
  (t) => [index("idx_tracked_popularity").on(t.popularityScore)],
);

export const cardPriceHistory = sqliteTable(
  "card_price_history",
  {
    id: integer("id").primaryKey({ autoIncrement: true }),
    cardId: text("card_id")
      .notNull()
      .references(() => pokemonCards.id),
    source: text("source", { enum: PRICE_SOURCES }).notNull(),
    variant: text("variant", { enum: CARD_VARIANTS }).notNull(),
    currency: text("currency", { enum: ["USD", "EUR"] }).notNull(),
    priceMinor: integer("price_minor").notNull(),
    /** UTC calendar day "YYYY-MM-DD"; max one observation per day (unique below). */
    recordedDate: text("recorded_date").notNull(),
    observedAt: integer("observed_at", { mode: "timestamp_ms" }).notNull(),
    sourceUpdatedAt: text("source_updated_at"),
    /** "daily" observation or "monthly" retention aggregate. */
    granularity: text("granularity", { enum: ["daily", "monthly"] })
      .default("daily")
      .notNull(),
  },
  (t) => [
    uniqueIndex("uq_history_card_source_variant_currency_date").on(
      t.cardId,
      t.source,
      t.variant,
      t.currency,
      t.recordedDate,
    ),
    index("idx_history_card_lookup").on(t.cardId, t.variant, t.source, t.recordedDate),
    index("idx_history_recorded_date").on(t.recordedDate),
  ],
);

// ── Graded (PSA) prices — sourced from eBay lowest-listing lookups ────────────
// Orthogonal to print variant and separate from the TCGplayer/variant pricing
// above: eBay graded "from" prices are per card+grade. Only psa9/psa10 are
// stored here (raw is TCGplayer). Populated on-view by the eBay refresh and
// snapshotted daily into the history table (forward-only, viewed cards).

export const cardGradedPrices = sqliteTable(
  "card_graded_prices",
  {
    cardId: text("card_id")
      .notNull()
      .references(() => pokemonCards.id),
    grade: text("grade", { enum: GRADES }).notNull(),
    currency: text("currency", { enum: ["USD", "EUR"] }).notNull(),
    /** Lowest current eBay listing ("from $X") in minor units. */
    fromMinor: integer("from_minor").notNull(),
    observedAt: integer("observed_at", { mode: "timestamp_ms" }).notNull(),
  },
  (t) => [primaryKey({ columns: [t.cardId, t.grade, t.currency] })],
);

export const cardGradedPriceHistory = sqliteTable(
  "card_graded_price_history",
  {
    id: integer("id").primaryKey({ autoIncrement: true }),
    cardId: text("card_id")
      .notNull()
      .references(() => pokemonCards.id),
    grade: text("grade", { enum: GRADES }).notNull(),
    currency: text("currency", { enum: ["USD", "EUR"] }).notNull(),
    priceMinor: integer("price_minor").notNull(),
    recordedDate: text("recorded_date").notNull(),
    observedAt: integer("observed_at", { mode: "timestamp_ms" }).notNull(),
    granularity: text("granularity", { enum: ["daily", "monthly"] })
      .default("daily")
      .notNull(),
  },
  (t) => [
    uniqueIndex("uq_graded_history_card_grade_currency_date").on(
      t.cardId,
      t.grade,
      t.currency,
      t.recordedDate,
    ),
    index("idx_graded_history_lookup").on(t.cardId, t.grade, t.recordedDate),
  ],
);

// ── Collection ───────────────────────────────────────────────────────────────

export const collectionEntries = sqliteTable(
  "collection_entries",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    cardId: text("card_id")
      .notNull()
      .references(() => pokemonCards.id),
    quantity: integer("quantity").notNull(),
    variant: text("variant", { enum: CARD_VARIANTS }).notNull(),
    /** Grade is orthogonal to print variant: a card can be raw or PSA-graded.
     * Graded entries are valued by eBay graded prices, not TCGplayer. */
    grade: text("grade", { enum: GRADES }).default("raw").notNull(),
    condition: text("condition", { enum: CONDITIONS }).default("Near Mint").notNull(),
    language: text("language").default("English").notNull(),
    purchasePriceMinor: integer("purchase_price_minor"),
    purchaseCurrency: text("purchase_currency", { enum: ["USD", "EUR"] })
      .default("USD")
      .notNull(),
    /** "YYYY-MM-DD". */
    purchaseDate: text("purchase_date"),
    /** Plain text only — never rendered as HTML. */
    notes: text("notes"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("idx_collection_user").on(t.userId),
    index("idx_collection_user_card").on(t.userId, t.cardId),
    index("idx_collection_user_updated").on(t.userId, t.updatedAt),
    index("idx_collection_card").on(t.cardId),
  ],
);

/** A user's favourited Pokémon (by national dex number) for the Pokédex page. */
export const pokedexFavorites = sqliteTable(
  "pokedex_favorites",
  {
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    dex: integer("dex").notNull(),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.dex] }), index("idx_pokedex_fav_user").on(t.userId)],
);

// ── Binders ──────────────────────────────────────────────────────────────────

export const binders = sqliteTable(
  "binders",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    description: text("description"),
    visibility: text("visibility", { enum: ["private", "unlisted", "public"] })
      .default("private")
      .notNull(),
    /** 128-bit random share slug; null when sharing disabled. */
    publicSlug: text("public_slug").unique(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("idx_binders_user").on(t.userId)],
);

export const binderSlots = sqliteTable(
  "binder_slots",
  {
    id: text("id").primaryKey(),
    binderId: text("binder_id")
      .notNull()
      .references(() => binders.id, { onDelete: "cascade" }),
    collectionEntryId: text("collection_entry_id").references(() => collectionEntries.id, {
      onDelete: "set null",
    }),
    /** Denormalized for public views (never exposes entry purchase data). */
    cardId: text("card_id").references(() => pokemonCards.id),
    pageNumber: integer("page_number").notNull(),
    side: text("side", { enum: ["front", "back"] }).notNull(),
    /** 1–9 within a 9-pocket page. */
    slotNumber: integer("slot_number").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("uq_binder_slot_position").on(t.binderId, t.pageNumber, t.side, t.slotNumber),
    index("idx_binder_slots_binder_page").on(t.binderId, t.pageNumber),
    index("idx_binder_slots_entry").on(t.collectionEntryId),
  ],
);

// ── Wishlist & alerts ────────────────────────────────────────────────────────

export const wishlistItems = sqliteTable(
  "wishlist_items",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    cardId: text("card_id")
      .notNull()
      .references(() => pokemonCards.id),
    variant: text("variant", { enum: CARD_VARIANTS }).notNull(),
    targetPriceMinor: integer("target_price_minor"),
    currency: text("currency", { enum: ["USD", "EUR"] })
      .default("USD")
      .notNull(),
    alertDirection: text("alert_direction", { enum: ["below", "above"] })
      .default("below")
      .notNull(),
    alertEnabled: integer("alert_enabled", { mode: "boolean" }).default(false).notNull(),
    /** Last observed side of the threshold ("below"/"above"); alerts fire only on crossings. */
    priorThresholdState: text("prior_threshold_state", { enum: ["below", "above"] }),
    lastAlertedAt: integer("last_alerted_at", { mode: "timestamp_ms" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("uq_wishlist_user_card_variant_currency").on(
      t.userId,
      t.cardId,
      t.variant,
      t.currency,
    ),
    index("idx_wishlist_user").on(t.userId),
    index("idx_wishlist_card").on(t.cardId),
    index("idx_wishlist_alerts").on(t.alertEnabled, t.cardId),
  ],
);

// ── Set goals & progress ─────────────────────────────────────────────────────

export const setGoals = sqliteTable(
  "set_goals",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    setId: text("set_id")
      .notNull()
      .references(() => pokemonSets.id),
    checklistMode: text("checklist_mode", { enum: ["standard", "variant"] })
      .default("standard")
      .notNull(),
    /** "YYYY-MM-DD". */
    targetDate: text("target_date"),
    pinned: integer("pinned", { mode: "boolean" }).default(false).notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("uq_set_goals_user_set_mode").on(t.userId, t.setId, t.checklistMode),
    index("idx_set_goals_user").on(t.userId),
  ],
);

export const setProgressCache = sqliteTable(
  "set_progress_cache",
  {
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    setId: text("set_id")
      .notNull()
      .references(() => pokemonSets.id),
    checklistMode: text("checklist_mode", { enum: ["standard", "variant"] }).notNull(),
    ownedCount: integer("owned_count").notNull(),
    totalCount: integer("total_count").notNull(),
    missingCount: integer("missing_count").notNull(),
    missingValueMinor: integer("missing_value_minor"),
    calculatedAt: integer("calculated_at", { mode: "timestamp_ms" }).notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.setId, t.checklistMode] })],
);

// ── Portfolio snapshots ──────────────────────────────────────────────────────

export const portfolioSnapshots = sqliteTable(
  "portfolio_snapshots",
  {
    id: integer("id").primaryKey({ autoIncrement: true }),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    /** UTC calendar day "YYYY-MM-DD". */
    snapshotDate: text("snapshot_date").notNull(),
    currency: text("currency", { enum: ["USD", "EUR"] }).notNull(),
    marketValueMinor: integer("market_value_minor").notNull(),
    /** Cost basis covering only entries with a recorded purchase price. */
    costBasisMinor: integer("cost_basis_minor").notNull(),
    /** P/L over entries having BOTH purchase price and current price. */
    unrealizedPlMinor: integer("unrealized_pl_minor").notNull(),
    uniqueCardCount: integer("unique_card_count").notNull(),
    totalQuantity: integer("total_quantity").notNull(),
    pricedEntryCount: integer("priced_entry_count").notNull(),
    unpricedEntryCount: integer("unpriced_entry_count").notNull(),
    calculatedAt: integer("calculated_at", { mode: "timestamp_ms" }).notNull(),
    granularity: text("granularity", { enum: ["daily", "monthly"] })
      .default("daily")
      .notNull(),
  },
  (t) => [
    uniqueIndex("uq_snapshot_user_date_currency").on(t.userId, t.snapshotDate, t.currency),
    index("idx_snapshots_user_date").on(t.userId, t.snapshotDate),
  ],
);

// ── Notifications & alert events ─────────────────────────────────────────────

export const notifications = sqliteTable(
  "notifications",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    type: text("type", { enum: ["price_alert", "import_finished", "system"] }).notNull(),
    title: text("title").notNull(),
    message: text("message").notNull(),
    payloadJson: text("payload_json"),
    readAt: integer("read_at", { mode: "timestamp_ms" }),
    createdAt: createdAt(),
  },
  (t) => [index("idx_notifications_user_read").on(t.userId, t.readAt, t.createdAt)],
);

export const priceAlertEvents = sqliteTable(
  "price_alert_events",
  {
    id: text("id").primaryKey(),
    wishlistItemId: text("wishlist_item_id")
      .notNull()
      .references(() => wishlistItems.id, { onDelete: "cascade" }),
    cardId: text("card_id")
      .notNull()
      .references(() => pokemonCards.id),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    priceMinor: integer("price_minor").notNull(),
    currency: text("currency", { enum: ["USD", "EUR"] }).notNull(),
    deliveryInApp: integer("delivery_in_app", { mode: "boolean" }).default(false).notNull(),
    deliveryEmail: integer("delivery_email", { mode: "boolean" }).default(false).notNull(),
    deliveryError: text("delivery_error"),
    triggeredAt: integer("triggered_at", { mode: "timestamp_ms" }).notNull(),
  },
  (t) => [index("idx_alert_events_user").on(t.userId, t.triggeredAt)],
);

// ── Jobs ─────────────────────────────────────────────────────────────────────

export const importJobs = sqliteTable(
  "import_jobs",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    status: text("status", {
      enum: ["pending", "running", "completed", "failed", "cancelled"],
    })
      .default("pending")
      .notNull(),
    mode: text("mode", { enum: ["append", "merge"] }).notNull(),
    totalRows: integer("total_rows").default(0).notNull(),
    processedRows: integer("processed_rows").default(0).notNull(),
    successfulRows: integer("successful_rows").default(0).notNull(),
    failedRows: integer("failed_rows").default(0).notNull(),
    /** Validated rows waiting to be applied (cleared on completion). */
    payloadJson: text("payload_json"),
    errorReportJson: text("error_report_json"),
    createdAt: createdAt(),
    startedAt: integer("started_at", { mode: "timestamp_ms" }),
    completedAt: integer("completed_at", { mode: "timestamp_ms" }),
  },
  (t) => [index("idx_import_jobs_user").on(t.userId, t.createdAt)],
);

export const SYNC_JOB_TYPES = [
  "catalog_sets",
  "catalog_cards_page",
  "price_history_record",
  "portfolio_snapshots",
  "alerts_evaluate",
  "retention_aggregate",
  "progress_cache_rebuild",
  "import_apply",
] as const;

export const syncJobs = sqliteTable(
  "sync_jobs",
  {
    id: text("id").primaryKey(),
    type: text("type", { enum: SYNC_JOB_TYPES }).notNull(),
    status: text("status", {
      enum: ["pending", "running", "completed", "failed", "cancelled"],
    })
      .default("pending")
      .notNull(),
    /** Opaque progress cursor (e.g. cards page number). */
    cursor: text("cursor"),
    payloadJson: text("payload_json"),
    /** Idempotency key: at most one open job per key (unique below, nullable). */
    idempotencyKey: text("idempotency_key"),
    attemptCount: integer("attempt_count").default(0).notNull(),
    maxAttempts: integer("max_attempts").default(5).notNull(),
    /** Lease: a claimed job is invisible until this expires (recovery-safe). */
    lockedUntil: integer("locked_until", { mode: "timestamp_ms" }),
    runAfter: integer("run_after", { mode: "timestamp_ms" }),
    errorMessage: text("error_message"),
    createdAt: createdAt(),
    startedAt: integer("started_at", { mode: "timestamp_ms" }),
    completedAt: integer("completed_at", { mode: "timestamp_ms" }),
  },
  (t) => [
    index("idx_sync_jobs_claim").on(t.status, t.runAfter, t.lockedUntil),
    index("idx_sync_jobs_type_status").on(t.type, t.status),
    uniqueIndex("uq_sync_jobs_idempotency").on(t.idempotencyKey),
  ],
);

export const syncJobLogs = sqliteTable(
  "sync_job_logs",
  {
    id: integer("id").primaryKey({ autoIncrement: true }),
    jobId: text("job_id")
      .notNull()
      .references(() => syncJobs.id, { onDelete: "cascade" }),
    level: text("level", { enum: ["debug", "info", "warn", "error"] }).notNull(),
    event: text("event").notNull(),
    metadataJson: text("metadata_json"),
    createdAt: createdAt(),
  },
  (t) => [index("idx_sync_job_logs_job").on(t.jobId, t.createdAt)],
);

// ── Admin audit ──────────────────────────────────────────────────────────────

export const adminAuditLogs = sqliteTable(
  "admin_audit_logs",
  {
    id: text("id").primaryKey(),
    /** Not FK-cascaded: audit trail must survive account deletion. */
    adminUserId: text("admin_user_id").notNull(),
    action: text("action").notNull(),
    targetType: text("target_type"),
    targetId: text("target_id"),
    metadataJson: text("metadata_json"),
    createdAt: createdAt(),
  },
  (t) => [index("idx_audit_admin").on(t.adminUserId, t.createdAt)],
);

// ── Sync run bookkeeping (full-sync completion tracking, SPEC §15) ───────────

/**
 * Short-lived atomic counters (rate-limit windows, PTCG API daily budget).
 * Kept in D1 instead of KV: the Workers Free plan allows only 1k KV writes/day
 * account-wide — per-request KV counter writes exhausted it and took search
 * down with 500s (2026-07-17). D1 allows 100k writes/day and its UPSERT is
 * atomic, which KV never was. Expired rows are pruned by the daily cron.
 */
export const counters = sqliteTable("counters", {
  key: text("key").primaryKey(),
  value: integer("value").notNull().default(0),
  /** Unix epoch seconds after which the row is dead (prune + ignore). */
  expiresAt: integer("expires_at").notNull(),
});

/**
 * Better Auth secondary storage (sessions, verification values, rate-limit
 * counters), backed by D1 instead of KV. On the Free plan KV caps at 1k
 * writes/day and Better Auth writes on every auth request (session + rate
 * limiter); once exhausted, an unhandled KV put() rejection 500ed the entire
 * auth handler (register + login dead, 2026-07-18). D1's budget is far larger.
 * `expiresAt` is unix epoch seconds; null = no TTL (persists until deleted).
 */
export const authKv = sqliteTable("auth_kv", {
  key: text("key").primaryKey(),
  value: text("value").notNull(),
  expiresAt: integer("expires_at"),
});

/** TTL cache for eBay API responses (OAuth app token + per-card Browse prices),
 * in D1 (not KV — Free-plan write cap). `expiresAt` is unix epoch seconds. */
export const ebayCache = sqliteTable("ebay_cache", {
  key: text("key").primaryKey(),
  value: text("value").notNull(),
  expiresAt: integer("expires_at").notNull(),
});

export const syncRuns = sqliteTable(
  "sync_runs",
  {
    id: text("id").primaryKey(),
    kind: text("kind", { enum: ["catalog_full", "catalog_delta"] }).notNull(),
    status: text("status", { enum: ["running", "completed", "failed"] })
      .default("running")
      .notNull(),
    totalPages: integer("total_pages"),
    completedPages: integer("completed_pages").default(0).notNull(),
    cardsUpserted: integer("cards_upserted").default(0).notNull(),
    setsUpserted: integer("sets_upserted").default(0).notNull(),
    pricesUpserted: integer("prices_upserted").default(0).notNull(),
    malformedSkipped: integer("malformed_skipped").default(0).notNull(),
    apiRequestCount: integer("api_request_count").default(0).notNull(),
    startedAt: integer("started_at", { mode: "timestamp_ms" }).notNull(),
    completedAt: integer("completed_at", { mode: "timestamp_ms" }),
    errorMessage: text("error_message"),
  },
  (t) => [index("idx_sync_runs_kind_status").on(t.kind, t.status, t.startedAt)],
);
